(()=>{"use strict";window.NAILS.ADMIN.registerPlugin("nails/module-email","UserTabSubscriptions",(function(s){return new class{constructor(s){this.adminController=s,console.log(s),this.init()}init(){$(".js-email-subscriptions").find(".js-subscribe-action").on("click",(s=>{s.preventDefault(),s.stopPropagation();let e=$(s.currentTarget),i=e.closest(".js-row"),t=i.data("type"),r=i.closest(".js-email-subscriptions").data("user-id");switch(e.data("action")){case"subscribe":this.subscribe(r,t,i);break;case"unsubscribe":this.unsubscribe(r,t,i)}}))}subscribe(s,e,i){this.api(s,e,"subscribe")&&this.setLabel(i,"Subscribed").setStatus(i,"success").setHint(i,"User will receive this type of email").showUnsubscribeButton(i)}unsubscribe(s,e,i){this.api(s,e,"unsubscribe")&&this.setLabel(i,"Unsubscribed").setStatus(i,"danger").setHint(i,"User will not received this type of email").showSubscribeButton(i)}async api(s,e,i){try{let t;if("subscribe"===i)t=`${window.SITE_URL}/api/email/admin/subscribe`;else{if("unsubscribe"!==i)throw new Error("Invalid action; must be subscribe or unsubscribe");t=`${window.SITE_URL}/api/email/admin/unsubscribe`}const r={userId:s,type:e},n=await fetch(t,{method:"PUT",headers:{"Content-Type":"application/json;charset=UTF-8"},body:JSON.stringify(r)});if(!n.ok)throw new Error("Network response was not ok "+n.statusText);await n.json(),this.adminController.log(`Successfully set ${s} as ${i} from ${e}`)}catch(s){return this.adminController.error("Error:",s),!1}return!0}setLabel(s,e){return s.find(".js-label").text(e),this}setStatus(s,e){return s.find(".js-status").removeClass("success danger").addClass(e),this}setHint(s,e){return s.find(".js-label").attr("aria-label",e),this}showSubscribeButton(s){return s.find(".js-subscribe-action[data-action=unsubscribe]").addClass("hidden"),s.find(".js-subscribe-action[data-action=subscribe]").removeClass("hidden"),this}showUnsubscribeButton(s){return s.find(".js-subscribe-action[data-action=unsubscribe]").removeClass("hidden"),s.find(".js-subscribe-action[data-action=subscribe]").addClass("hidden"),this}}(s)}))})();